package com.nazofobi.arrivalalarm

import java.util.Locale

/** A passive provider only relays updates generated by other clients. */
internal object ActiveJourneyLocationProviderSelection {
    fun choose(enabledProviders: List<String>): String? {
        // Android normally returns canonical lowercase names, but OEM/provider
        // wrappers can add whitespace or change casing. Normalize only for
        // ranking and filtering; preserve the original name for the API call.
        val candidates = enabledProviders
            .map { provider -> provider to provider.trim().lowercase(Locale.ROOT) }
            .filter { (_, normalized) -> normalized.isNotEmpty() }

        return candidates.firstOrNull { (_, normalized) -> normalized == "gps" }?.first
            ?: candidates.firstOrNull { (_, normalized) -> normalized == "network" }?.first
            ?: candidates.firstOrNull { (_, normalized) -> normalized != "passive" }?.first
    }
}
